# -*- coding: utf-8 -*-
"""Novos Poderes de Classe — Heróis de Arton (Cap. 1, p. 54–77).

Inclui todos os novos poderes de classe para as 12 classes básicas:
Arcanista, Bárbaro, Bardo, Bucaneiro, Caçador, Cavaleiro, Clérigo,
Druida, Guerreiro (+ 7 novos efeitos de Golpe Pessoal), Inventor,
Ladino, Lutador, Nobre e Paladino.
"""
from typing import Dict, Any, List
from .dados_suplementos import FONTE_HEROIS


def _pc(
    classe: str,
    nome: str,
    descricao: str,
    requisitos: List[str] | None = None,
    efeitos: Dict[str, Any] | None = None,
    custo_pm: int = 0,
) -> Dict[str, Any]:
    ef: Dict[str, Any] = dict(efeitos or {})
    if custo_pm and "custo_pm" not in ef:
        ef["custo_pm"] = custo_pm
    if classe == "Cavaleiro" and nome.startswith("Postura de Combate:"):
        ef.setdefault("postura_combate", {"acao": "movimento", "custo_pm": 2, "duracao": "cena"})
    if classe == "Clérigo" and nome.startswith("Missa:"):
        ef.setdefault("missa", {"tempo": "1 hora", "custo_to": 25, "duracao": "1 dia"})
    if not ef:
        ef["nota"] = descricao
    d: Dict[str, Any] = {
        "nome": nome,
        "tipo": f"Poder de {classe}",
        "classe": classe,
        "nivel": 0,
        "fonte": FONTE_HEROIS,
        "descricao": descricao,
        "requisitos": list(requisitos or []),
        "efeitos": ef,
    }
    if custo_pm:
        d["custo_pm"] = custo_pm
    return d


